<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue';
import type { Comparison, Draft, DraftLine, DraftLineInput, GeneratedLink, Hospital, Manufacturer, OrderSummary, OrderView, QuoteDeliveryVersion, PurchaseInput, Session, SupplierTask, MarkupMethod } from '@quote/contracts';
import { ApiFailure, operationInFlight, hospitalResultForOperation, canRetry, checkOperation, mutate, pending, request, retryOperation, session, setSession } from '../../api';
import { canManageOrder, pricingInputs, recommendation, restoreMarkup, validPositive, type MarkupState } from '../../domain';
import QuoteDelivery from '../../components/QuoteDelivery.vue';
import OrderArchive from '../../components/OrderArchive.vue';
import Receivables from '../../components/Receivables.vue';
import FinanceWorkspace from '../../components/FinanceWorkspace.vue';
import HospitalWorkspace from '../../components/HospitalWorkspace.vue';
import HistoricalOrders from '../../components/HistoricalOrders.vue';
import HospitalAnalytics from '../../components/HospitalAnalytics.vue';
import SourceFiles from '../../components/SourceFiles.vue';
import {historicalOperationTarget} from '../../../../../packages/historical-client/src';
import {readSourcePending,sourceOperationTarget,type SourceReference} from '../../../../../packages/source-client/src';
import {sourceDescriptorStorage} from '../../source-files';
import type {CatalogVariant} from '@quote/contracts';
import {financeOperationTarget,type FinanceTarget} from '../../../../../packages/finance-client/src';
import PriceHistory from '../../components/PriceHistory.vue';
import { canProcessOrder } from '@quote/archive-client';
import type { ArchiveOrder } from '@quote/contracts';
import { committedOperationNotice, receivableForOperation, type StoredOperation } from '../../pending';

const screen=ref<'orders'|'purchase'|'inquiry'|'pricing'|'delivery'|'archive'|'receivables'|'finance'|'hospital'|'historical'|'analytics'|'sourceRecovery'>('orders');
const reminderConfiguration=ref<{available:boolean;templateId?:string}>({available:false});
const financeBusy=ref(false),financeTarget=ref<FinanceTarget|null>(null),financeRef=ref<{refresh:()=>Promise<void>;openAfterRecovery:(target:FinanceTarget)=>Promise<void>;canLeave:()=>boolean}|null>(null);
const sourceBusy=ref(false),hospitalBusy=ref(false),historicalBusy=ref(false),analyticsBusy=ref(false),sourceRecovery=ref<SourceReference|null>(null),catalogOpen=ref(false),catalogKeyword=ref(''),catalogItems=ref<CatalogVariant[]>([]),bindingRole=ref<'sales'|'hospital'>('sales');
const historicalRef=ref<{refresh:()=>Promise<void>;openAfterRecovery:(id?:string)=>Promise<void>;canLeave:()=>boolean}|null>(null),hospitalRef=ref<{refresh:()=>Promise<void>;openAfterRecovery:(id?:string)=>Promise<void>;canLeave:()=>boolean}|null>(null),analyticsRef=ref<{refresh:()=>Promise<void>}|null>(null);
const running=ref(false), deliveryBusy=ref(false), archiveBusy=ref(false), historyBusy=ref(false),receivablesBusy=ref(false),receivablesDirty=ref(false);
const busy=computed(()=>running.value||deliveryBusy.value||archiveBusy.value||historyBusy.value||receivablesBusy.value||financeBusy.value||sourceBusy.value||hospitalBusy.value||historicalBusy.value||analyticsBusy.value);
const interactionLocked=computed(()=>busy.value||receivablesDirty.value||!!pending.value||!!orderAction.value);
const error=ref(''), notice=ref(''), conflict=ref(false), foundNotCommitted=ref(false);
const hasChanges=ref(false);
const receivablesRef=ref<{refresh:()=>Promise<void>;openAfterRecovery:(id:string)=>Promise<void>}|null>(null);
const archiveRef=ref<{refresh:()=>Promise<void>}|null>(null);
const deliveryRef=ref<{refresh:()=>Promise<void>}|null>(null);
const loginMode=ref<'trial'|'wechat'>('trial'), loginName=ref(''), password=ref(''), bindTicket=ref('');
const hospitals=ref<Hospital[]>([]), manufacturers=ref<Manufacturer[]>([]), orders=ref<OrderSummary[]>([]);
const order=ref<OrderView|null>(null), comparison=ref<Comparison|null>(null), draft=ref<Draft|null>(null);
const hospitalIndex=ref(0), purchaserIndex=ref(0), receivedDate=ref(today()), lines=ref<PurchaseInput[]>([emptyLine()]);
const selectedFactory=ref([0,1]), generated=ref<Record<string,GeneratedLink>>({});
const selectedLineIds=ref<string[]>([]), activeLineId=ref(''), batchScope=ref(0), methodIndex=ref(0), parameter=ref(''), undo=ref<(MarkupState&{purchaseLineId:string})[]|null>(null);
const orderAction=ref<'revisions'|'void'|null>(null),orderActionReason=ref('');
const danger=ref<{mode:'regenerate'|'requote'|'cancel';task:SupplierTask;reason:string}|null>(null);
const methods:MarkupMethod[]=['fixed','percent','multiplier'];const methodLabels=['请选择加价方式','固定金额加价','比例加价（%）','高开倍率加价'];
const hospital=computed(()=>hospitals.value[hospitalIndex.value]);
const purchaser=computed(()=>hospital.value?.purchasers[purchaserIndex.value]);
const isDraftOrder=computed(()=>!order.value||order.value.status==='draft');
const activeLine=computed(()=>draft.value?.lines.find(l=>l.purchaseLineId===activeLineId.value));
const activeComparison=computed(()=>comparison.value?.lines.find(l=>l.purchaseLineId===activeLineId.value));
const pricedLines=computed(()=>draft.value?.lines.filter(l=>l.kind==='priced'&&l.baseValid)||[]);
const batchLines=computed(()=>pricedLines.value.filter(l=>batchScope.value===0||selectedLineIds.value.includes(l.purchaseLineId)));
const changedSupplier=computed(()=>draft.value?.lines.some(l=>l.hasNewSupplierData));
const allMissing=computed(()=>!!draft.value?.lines.length&&draft.value.lines.every(l=>l.kind==='missing'&&l.supplyValid!==false));
const readOnly=computed(()=>!!order.value&&!canManageOrder(order.value));
const editingLocked=computed(()=>interactionLocked.value||readOnly.value);
const stateLabels:Record<string,string>={quoted:'有效报价',unavailable:'无法供货',pending:'待提交',expired:'报价已过期',requote:'重新报价中',cancelled:'任务已取消'};
function today(){const d=new Date(Date.now()+8*3600000);return d.toISOString().slice(0,10);}
function emptyLine():PurchaseInput{return {name:'',spec:'',quantity:'',checked:false,remark:'',sourceType:'custom_input'};}
function money(value:string|null|undefined){return value==null?'—':value;}
function stamp(value:string|null){return value?new Date(new Date(value).getTime()+8*3600000).toISOString().replace('T',' ').slice(0,16)+' 北京时间':'未生成';}
function changed(){hasChanges.value=true;notice.value='有未保存修改';}
function ensureWritable(){if(pending.value)throw new Error('上次操作结果尚未核实，请先核对。');if(order.value&&!canManageOrder(order.value))throw new Error('当前订单只读，已完成或已作废订单不能继续询价、计价。');}
function resetWorkspace(){order.value=null;comparison.value=null;draft.value=null;generated.value={};orders.value=[];hospitals.value=[];manufacturers.value=[];screen.value='orders';danger.value=null;notice.value='';error.value='';undo.value=null;selectedLineIds.value=[];activeLineId.value='';methodIndex.value=0;parameter.value='';foundNotCommitted.value=false;hasChanges.value=false;}
function resetOrderContext(){draft.value=null;comparison.value=null;generated.value={};danger.value=null;selectedLineIds.value=[];activeLineId.value='';methodIndex.value=0;parameter.value='';batchScope.value=0;undo.value=null;hasChanges.value=false;notice.value='';selectedFactory.value=[0,1];}
watch(()=>session.value?.user.id,(id,old)=>{if(id!==old)resetWorkspace();},{flush:'sync'});
function pickValue(event:unknown){return Number((event as {detail:{value:string}}).detail.value);}
async function confirm(title:string,content:string){return new Promise<boolean>(resolve=>uni.showModal({title,content,confirmColor:'#216349',success:r=>resolve(r.confirm)}));}
async function run(work:()=>Promise<void>,recovery=false){if(recovery?(running.value||operationInFlight.value):busy.value)return;running.value=true;error.value='';conflict.value=false;try{await work();}catch(e){const message=e instanceof Error?e.message:'操作未完成，请重试';if(e instanceof ApiFailure){if(e.status===401||e.code==='UNAUTHORIZED'||e.code==='SESSION_EXPIRED'||e.code==='UNAUTHENTICATED')setSession(null);conflict.value=/VERSION|CONFLICT|STALE/.test(e.code);}error.value=message;}finally{running.value=false;}}
async function bootstrap(){if(session.value?.user.role==='hospital'){const original=sourceOperationTarget(readSourcePending(session.value.user.id,sourceDescriptorStorage));sourceRecovery.value=original;screen.value=original?'sourceRecovery':'hospital';return;}if(session.value?.user.role!=='salesperson')throw new Error('小程序仅供销售员和医院采购员使用，管理员请使用PC端。');const [b,o]=await Promise.all([request<{hospitals:Hospital[];manufacturers:Manufacturer[]}>('/sales/bootstrap'),request<{items:OrderSummary[]}>('/sales/purchase-orders')]);hospitals.value=b.hospitals;manufacturers.value=b.manufacturers;orders.value=o.items;try{reminderConfiguration.value=await request('/sales/receivable-reminders/config');}catch{reminderConfiguration.value={available:false};}const source=sourceOperationTarget(readSourcePending(session.value.user.id,sourceDescriptorStorage));if(source){sourceRecovery.value=source;screen.value='sourceRecovery';}else if(historicalOperationTarget(pending.value))screen.value='historical';}
async function login(){await run(async()=>{const value=await request<Session>(bindTicket.value?'/auth/miniapp/bind-sales':'/auth/trial/password-login','POST',{loginName:loginName.value,password:password.value,...(bindTicket.value?{bindTicket:bindTicket.value}:{})});setSession(value);password.value='';bindTicket.value='';await bootstrap();});}
async function wechatLogin(){await run(async()=>{const code=await new Promise<string>((resolve,reject)=>uni.login({provider:'weixin',success:r=>r.code?resolve(r.code):reject(new Error('未取得微信登录凭证')),fail:()=>reject(new Error('请在微信开发者工具或微信小程序内使用微信登录。'))}));const value=await request<Session|{authState:'identity_unbound';bindTicket:string}>('/auth/miniapp/login','POST',{loginCode:code});if(value.authState==='authenticated'){setSession(value);await bootstrap();}else{bindTicket.value=value.bindTicket;notice.value='微信身份尚未绑定，请填写内部销售账号完成绑定。';}});}
async function hospitalPhoneLogin(event:unknown){const code=(event as {detail?:{code?:string}})?.detail?.code;if(!code){error.value='请允许使用已建档的手机号；未授权时不会创建账号。';return;}await run(async()=>{if(!bindTicket.value)throw new Error('微信身份凭证已失效，请重新微信登录。');const value=await request<Session>('/auth/miniapp/hospital-phone-login','POST',{bindTicket:bindTicket.value,phoneCode:code});setSession(value);bindTicket.value='';await bootstrap();});}
async function logout(){if(running.value||operationInFlight.value)return;if(!pending.value){const child=session.value?.user.role==='hospital'?hospitalRef.value:screen.value==='finance'?financeRef.value:screen.value==='historical'?historicalRef.value:null;if(child&&!child.canLeave()){error.value='当前页面有未保存内容或未完成操作，请先保存或明确放弃后再退出。';return;}if(!await leaveUnsaved())return;}await run(async()=>{await request('/auth/logout','POST',{});setSession(null);order.value=null;draft.value=null;screen.value='orders';},true);}
async function startPurchase(){if(interactionLocked.value)return;if(hasChanges.value&&!await confirm('新建另一张采购单？','当前未保存修改将被放弃。'))return;resetOrderContext();order.value=null;hospitalIndex.value=0;purchaserIndex.value=0;receivedDate.value=today();lines.value=[emptyLine()];notice.value='';screen.value='purchase';}
async function leaveUnsaved(){if(receivablesDirty.value){error.value='请先完成登记或选择放弃并清空未提交回款后离开。';return false;}if(!hasChanges.value)return true;if(!await confirm('放弃未保存修改？','请先保存修改，或确认放弃后离开当前工作台。'))return false;resetOrderContext();return true;}
async function showOrders(){if(interactionLocked.value||!await leaveUnsaved())return;screen.value='orders';await run(bootstrap);}
async function showArchive(){if(interactionLocked.value||!await leaveUnsaved())return;screen.value='archive';}
async function showFinance(target:FinanceTarget|null=null){if(interactionLocked.value||!await leaveUnsaved())return;financeTarget.value=target;screen.value='finance';}
async function showReceivables(){if(interactionLocked.value||!await leaveUnsaved())return;screen.value='receivables';}
async function archiveProcess(item:ArchiveOrder){if(interactionLocked.value)return;if(!canProcessOrder(item)){error.value='当前订单只读，不能进入业务处理。';return;}await openOrder(item.id,true);}
function archiveFailure(e:unknown){const value=e as {status?:number;code?:string};error.value=e instanceof Error?e.message:'读取失败，请重试。';if(value?.status===401||['UNAUTHORIZED','SESSION_EXPIRED','UNAUTHENTICATED'].includes(value?.code||''))setSession(null);}
function viewInquiry(){if(interactionLocked.value)return;if(hasChanges.value){error.value='请先保存当前计价修改，再查看询价。';return;}screen.value='inquiry';}
function hydrateOrder(value:OrderView){order.value=value;lines.value=value.lines.map(l=>({...l,remark:l.remark||''}));receivedDate.value=value.receivedDate;hospitalIndex.value=Math.max(0,hospitals.value.findIndex(h=>h.id===value.hospitalId));purchaserIndex.value=Math.max(0,hospital.value?.purchasers.findIndex(p=>p.id===value.purchaserUserId)||0);hasChanges.value=false;}
async function fetchOrder(){if(order.value)order.value=await request<OrderView>('/sales/purchase-orders/'+order.value.id);}
async function openOrder(id:string,requireWritable=false){if(interactionLocked.value)return;if(hasChanges.value&&!await confirm('打开采购单？','当前未保存修改将被服务器数据替换。'))return;await run(async()=>{const value=await request<OrderView>('/sales/purchase-orders/'+id);if(requireWritable&&!canManageOrder(value))throw new Error('订单权限或状态已变化，当前仅可在历史档案查阅。');if(order.value?.id!==id)resetOrderContext();hydrateOrder(value);screen.value=order.value!.status==='draft'?'purchase':['quote_exported','quote_sent','completed','voided'].includes(order.value!.status)?'delivery':'inquiry';if(screen.value==='inquiry')await loadComparison();});}
async function refresh(){if(interactionLocked.value)return;if(screen.value==='hospital'){await hospitalRef.value?.refresh();return;}if(screen.value==='historical'){await historicalRef.value?.refresh();return;}if(screen.value==='analytics'){await analyticsRef.value?.refresh();return;}if(screen.value==='finance'){await financeRef.value?.refresh();return;}if(screen.value==='receivables'){await receivablesRef.value?.refresh();return;}if(screen.value==='delivery'){await deliveryRef.value?.refresh();return;}if(screen.value==='archive'){await archiveRef.value?.refresh();return;}if(hasChanges.value&&!await confirm('重新加载最新数据？','当前未保存修改将被服务器数据替换。'))return;await run(async()=>{if(!order.value||screen.value==='orders'){await bootstrap();return;}const value=await request<OrderView>('/sales/purchase-orders/'+order.value.id);hydrateOrder(value);if(value.status!=='draft'&&screen.value!=='delivery'){await loadComparison();if(screen.value==='pricing'&&canManageOrder(value))await loadDraft();}if(['completed','voided'].includes(value.status))screen.value='delivery';hasChanges.value=false;notice.value='已重新加载服务器数据';});}
function validatePurchase(){if(!order.value&&(!hospital.value||!purchaser.value))throw new Error('请选择医院及具体采购员。');if(!receivedDate.value)throw new Error('请选择实际接收日期。');if(!lines.value.length||lines.value.some(l=>!l.name.trim()||!validPositive(l.quantity)))throw new Error('每行须填写品名和大于 0、最多两位小数的数量。');}
async function persistPurchase(){ensureWritable();validatePurchase();const input=lines.value.map(l=>({...(l.id?{id:l.id}:{}),name:l.name,spec:l.spec,quantity:l.quantity,checked:l.checked,remark:l.remark||'',sourceType:l.sourceType||'custom_input',itemId:l.itemId??null,itemVariantId:l.itemVariantId??null,sourceFileId:l.sourceFileId??null,parsingJobId:l.parsingJobId??null,sourceRowNumber:l.sourceRowNumber??null}));const value=order.value?await mutate<OrderView>('保存采购校对','/sales/purchase-orders/'+order.value.id+'/revisions/'+order.value.revisionId+'/lines','PUT',{expectedVersion:order.value.version,lines:input,...order.value.receivedDateEditable?{receivedDate:receivedDate.value}:{}}):await mutate<OrderView>('新建采购单','/sales/purchase-orders','POST',{hospitalId:hospital.value!.id,purchaserUserId:purchaser.value!.id,receivedDate:receivedDate.value,lines:input});hydrateOrder(value);await fetchOrder();notice.value='采购草稿已保存';}
function beginOrderAction(action:'revisions'|'void'){if(interactionLocked.value||!order.value||readOnly.value)return;if(hasChanges.value){error.value='请先保存或放弃修改，再进行采购修订或整单作废。';return;}orderAction.value=action;orderActionReason.value='';}
async function commitOrderAction(){if(busy.value||pending.value||!order.value||!orderAction.value||!orderActionReason.value.trim())return;const action=orderAction.value;await run(async()=>{const result=await mutate<OrderView>(action==='revisions'?'创建下一采购修订':'整单作废','/sales/purchase-orders/'+order.value!.id+'/'+action,'POST',{expectedVersion:order.value!.version,reason:orderActionReason.value});resetOrderContext();hydrateOrder(result);orderAction.value=null;screen.value=action==='revisions'?'purchase':'delivery';notice.value=action==='revisions'?'须重新校对、冻结和询价；旧修订保持历史，不恢复旧入口。':'整张订单已作废，保留全部历史。';});}
async function sourceDraft(){await run(async()=>{if(order.value)return;if(!hospital.value||!purchaser.value||!receivedDate.value)throw new Error('请先选择医院、采购员和接收日期。');if(lines.value.some(l=>l.name||l.spec||l.quantity||l.remark))throw new Error('已有手工内容，请先完整保存或放弃修改后再建立资料草稿。');hydrateOrder(await mutate<OrderView>('新建原单资料草稿','/sales/purchase-orders','POST',{hospitalId:hospital.value.id,purchaserUserId:purchaser.value.id,receivedDate:receivedDate.value,lines:[]}));});}
async function sourceChanged(){await run(async()=>{if(order.value)hydrateOrder(await request<OrderView>('/sales/purchase-orders/'+order.value.id));});}
async function searchCatalog(){await run(async()=>{const r=await request<{items:CatalogVariant[]}>('/catalog/variants?keyword='+encodeURIComponent(catalogKeyword.value)+'&limit=100');catalogItems.value=r.items;catalogOpen.value=true;});}
function chooseCatalog(v:CatalogVariant){if(interactionLocked.value||readOnly.value)return;if(lines.value.length>=200){error.value='每单最多200行。';return;}const line={...emptyLine(),name:v.name,spec:v.specification,sourceType:'product_library' as const,itemId:v.itemId,itemVariantId:v.variantId};if(lines.value.length===1&&!lines.value[0].name&&!lines.value[0].quantity&&!lines.value[0].spec)lines.value=[line];else lines.value.push(line);catalogOpen.value=false;changed();}
async function showAnalysis(){if(interactionLocked.value||!await leaveUnsaved())return;screen.value='analytics';}
async function showHistorical(){if(interactionLocked.value||!await leaveUnsaved())return;screen.value='historical';}
async function analysisOrder(id:string){if(interactionLocked.value)return;screen.value='archive';await nextTick();await (archiveRef.value as any)?.openOrder?.(id);}
async function savePurchase(){await run(persistPurchase);}
async function freeze(){if(busy.value)return;if(!await confirm('冻结采购明细？','冻结后本版明细只读，厂家将按此明细报价。'))return;await run(async()=>{if(lines.value.some(l=>!l.checked))throw new Error('请逐行核对并勾选后再冻结。');await persistPurchase();await mutate('冻结采购明细','/sales/purchase-orders/'+order.value!.id+'/revisions/'+order.value!.revisionId+'/freeze','POST',{expectedVersion:order.value!.version});await fetchOrder();screen.value='inquiry';await loadComparison();notice.value='采购明细已冻结';});}
async function loadComparison(){if(order.value)comparison.value=await request<Comparison>('/sales/purchase-orders/'+order.value.id+'/comparison');}
function taskFor(slot:number){return order.value?.tasks.find(t=>t.slotNo===slot&&t.status!=='cancelled');}
async function assign(slot:1|2){await run(async()=>{ensureWritable();const factory=manufacturers.value[selectedFactory.value[slot-1]||0];if(!factory)throw new Error('暂无可选厂家，请联系管理员维护。');await mutate('选择询价厂家','/sales/purchase-order-revisions/'+order.value!.revisionId+'/supplier-tasks','POST',{expectedVersion:order.value!.version,slotNo:slot,manufacturerId:factory.id});await fetchOrder();await loadComparison();});}
async function generate(task:SupplierTask){await run(async()=>{ensureWritable();const result=await mutate<GeneratedLink>('生成厂家链接','/supplier-tasks/'+task.id+'/generate-link','POST',{expectedVersion:order.value!.version});if(result.url)generated.value[task.id]=result;await fetchOrder();notice.value=result.url?'链接已生成，请复制后发送厂家。':'原链接无法恢复，请重新生成。';});}
function copyLink(task:SupplierTask){if(interactionLocked.value)return;const url=generated.value[task.id]?.url;if(url)uni.setClipboardData({data:url,success:()=>{notice.value='链接已复制，请自行发送给对应厂家。';}});}
async function commitDanger(){if(busy.value||!danger.value)return;if(hasChanges.value&&draft.value){danger.value=null;error.value='请先返回计价保存当前修改，再重新询价或取消任务。';return;}const action=danger.value;if(!action.reason.trim()){error.value='请填写操作原因';return;}await run(async()=>{ensureWritable();const suffix=action.mode==='regenerate'?'regenerate-link':action.mode;const payload={expectedVersion:order.value!.version,reason:action.reason,...(action.mode==='regenerate'?{expectedLinkId:action.task.linkId}:{}),...(action.mode==='requote'?{expectedSubmissionId:action.task.submissionId}:{})};const result=await mutate<GeneratedLink>('厂家'+suffix,'/supplier-tasks/'+action.task.id+'/'+suffix,'POST',payload);delete generated.value[action.task.id];if(result?.url)generated.value[action.task.id]=result;danger.value=null;await fetchOrder();await loadComparison();if(draft.value)await loadDraft();notice.value=action.mode==='cancel'?'询价任务已取消':'新链接已生成，旧链接及已打开的旧页面已失效。';});}
async function enterPricing(){if(order.value?.quoteId&&!order.value.draftId){viewDelivery();return;}if(interactionLocked.value||readOnly.value)return;if(!comparison.value?.submittedCount)return;if(comparison.value.submittedCount===1&&!await confirm('提前进入计价？','另一厂家尚未完整提交。后到报价只更新候选，不自动改写计价草稿。'))return;await run(async()=>{ensureWritable();draft.value=await mutate<Draft>('进入计价','/sales/purchase-orders/'+order.value!.id+'/enter-pricing','POST',{expectedVersion:order.value!.version,allowEarly:comparison.value!.submittedCount===1});await fetchOrder();await loadComparison();screen.value='pricing';activeLineId.value=draft.value.lines[0]?.purchaseLineId||'';notice.value='';});}
async function loadDraft(){const versions=await request<{quoteId:string|null;items:QuoteDeliveryVersion[]}>('/sales/purchase-orders/'+order.value!.id+'/quote-versions');const current=versions.items.find(v=>v.quoteId===versions.quoteId&&v.status==='draft');if(!current||current.occupied){draft.value=null;screen.value='delivery';throw new Error(current?.occupied?'报价正在生成文件，请等待任务完成后再编辑。':'当前没有可编辑草稿，请查看报价交付或创建下一版本。');}draft.value=await request<Draft>('/sales/purchase-orders/'+order.value!.id+'/draft');if(!activeLineId.value||!draft.value.lines.some(l=>l.purchaseLineId===activeLineId.value))activeLineId.value=draft.value.lines[0]?.purchaseLineId||'';undo.value=null;hasChanges.value=false;}
async function refreshCandidates(){await run(async()=>{await fetchOrder();await loadComparison();const latest=await request<Draft>('/sales/purchase-orders/'+order.value!.id+'/draft');draft.value?.lines.forEach(line=>{const updated=latest.lines.find(l=>l.purchaseLineId===line.purchaseLineId);if(updated){line.baseValid=updated.baseSupplierQuoteLineId===line.baseSupplierQuoteLineId?updated.baseValid:line.baseValid;line.supplyValid=updated.supplyValid;line.hasNewSupplierData=updated.hasNewSupplierData;}});notice.value='已刷新报价候选，当前编辑值保留。';});}
async function continuePricing(){if(interactionLocked.value)return;if(readOnly.value){screen.value='delivery';return;}if(hasChanges.value&&draft.value?.orderId===order.value?.id){screen.value='pricing';return;}await run(async()=>{await loadDraft();await loadComparison();screen.value='pricing';});}
function toggleLine(id:string){if(interactionLocked.value)return;selectedLineIds.value=selectedLineIds.value.includes(id)?selectedLineIds.value.filter(x=>x!==id):[...selectedLineIds.value,id];}
async function applyBatch(){if(interactionLocked.value)return;try{ensureWritable();if(!draft.value)return;if(!methodIndex.value)throw new Error('请先选择加价方式。');if(!batchLines.value.length)throw new Error('没有可计价的目标行。');const method=methods[methodIndex.value-1];const updates=batchLines.value.map(l=>({l,value:recommendation(l.basePrice!,method,parameter.value)}));const targetCount=batchScope.value===0?draft.value.lines.length:selectedLineIds.value.length;if(!await confirm('确认批量加价？',methodLabels[methodIndex.value]+'，参数 '+parameter.value+'；影响 '+updates.length+' 行，跳过 '+(targetCount-updates.length)+' 行。仅更新推荐价。'))return;undo.value=updates.map(({l})=>({purchaseLineId:l.purchaseLineId,markupMethod:l.markupMethod,parameterValue:l.parameterValue,recommendedPrice:l.recommendedPrice}));updates.forEach(({l,value})=>{l.markupMethod=method;l.parameterValue=parameter.value;l.recommendedPrice=value;});hasChanges.value=true;notice.value='已更新 '+updates.length+' 行推荐价，请核对后另行采用为最终价。';error.value='';}catch(e){error.value=(e as Error).message;}}
function undoBatch(){if(interactionLocked.value)return;if(draft.value&&undo.value){const previous=undo.value;draft.value.lines=draft.value.lines.map(line=>{const old=previous.find(item=>item.purchaseLineId===line.purchaseLineId);return old?restoreMarkup(line,old):line;});undo.value=null;hasChanges.value=true;notice.value='已撤销最近一次批量加价，最终价和基准选择保留。';}}
function chooseBase(event:unknown){if(interactionLocked.value)return;const line=activeLine.value;if(!line)return;const cells=activeComparison.value?.cells.filter(c=>c.state==='quoted')||[];const c=cells[pickValue(event)];if(!c)return;line.baseSupplierQuoteLineId=c.supplierQuoteLineId;line.baseManufacturerName=c.manufacturerName;line.basePrice=c.price;line.baseValid=true;line.selectionMode='manual';line.finalConfirmed=false;line.recommendedPrice=line.markupMethod&&line.parameterValue?recommendation(c.price!,line.markupMethod,line.parameterValue):null;changed();}
function applyRecommended(line:DraftLine){if(interactionLocked.value)return;if(line.recommendedPrice){line.finalPrice=line.recommendedPrice;line.finalConfirmed=false;changed();}}
function finalChanged(line:DraftLine){line.finalConfirmed=false;changed();}
async function saveDraft(){await run(async()=>{ensureWritable();if(!draft.value)return;const value=draft.value;const inputs:DraftLineInput[]=pricingInputs(value.lines);draft.value=await mutate<Draft>('保存计价草稿','/quotes/'+value.quoteId+'/versions/'+value.id+'/draft','PUT',{expectedVersion:value.version,hospitalValidUntil:value.hospitalValidUntil,lines:inputs});undo.value=null;hasChanges.value=false;await fetchOrder();notice.value='计价草稿已保存到服务器';screen.value='delivery';});}
async function adopt(){if(interactionLocked.value)return;if(!draft.value)return;if(hasChanges.value){error.value='请先保存当前计价修改，再采用最新报价；也可重新加载放弃修改。';return;}if(!await confirm('采用最新厂家报价？','将更新所选行的厂家快照与推荐价，保留已保存最终价；基准变化的行需要重新确认。'))return;await run(async()=>{ensureWritable();const d=draft.value!;draft.value=await mutate<Draft>('采用最新厂家报价','/quotes/'+d.quoteId+'/versions/'+d.id+'/adopt-latest-supplier-quotes','POST',{expectedVersion:d.version,...(selectedLineIds.value.length?{lineIds:selectedLineIds.value}:{})});await fetchOrder();await loadComparison();notice.value='已采用最新报价，请重新核对受影响行。';});}
function viewDelivery(){if(interactionLocked.value)return;if(hasChanges.value){error.value='请先保存当前计价修改，再查看报价交付。';return;}screen.value='delivery';}
async function deliveryChanged(){if(order.value)await run(fetchOrder);}
async function editDeliveryDraft(){if(interactionLocked.value||readOnly.value)return;await run(async()=>{await fetchOrder();ensureWritable();await loadDraft();await loadComparison();screen.value='pricing';});}
function deliveryFailure(e:unknown){void run(async()=>{throw e;});}
function orderLabel(status:string){return ({draft:'待校对',frozen:'厂家询价',quote_draft:'计价草稿',quote_exported:'报价已导出',quote_sent:'报价已发送',completed:'已完成',voided:'已作废'} as Record<string,string>)[status]||status;}
async function returnAfterCommitted(operation:StoredOperation|null){if(operation?.path?.startsWith('/hospital/purchase-orders')){screen.value='hospital';await nextTick();const result=hospitalResultForOperation(operation);await hospitalRef.value?.openAfterRecovery(result?.id);notice.value='原采购需求操作已核实，请核对最新保存内容。';return;}if(historicalOperationTarget(operation)){screen.value='historical';await nextTick();await historicalRef.value?.openAfterRecovery(historicalOperationTarget(operation)?.orderId);return;}resetOrderContext();order.value=null;screen.value='orders';await bootstrap();notice.value=committedOperationNotice(operation);}
async function afterRecoveredPayment(operation:StoredOperation|null){const target=financeOperationTarget(operation);if(target){financeTarget.value=target;screen.value='finance';await nextTick();await financeRef.value?.openAfterRecovery(target);notice.value='原财务操作已核实，请核对最新账期和异常。';return;}const id=receivableForOperation(operation);if(!id)return;screen.value='receivables';await nextTick();await receivablesRef.value?.openAfterRecovery(id);notice.value='原回款操作已确认提交，请核对最新记录和余额。';}
async function checkPending(){let recovered:StoredOperation|null=null;await run(async()=>{const original=pending.value;const status=await checkOperation();foundNotCommitted.value=status==='not_found';if(status==='committed'){if(receivableForOperation(original)||financeOperationTarget(original))recovered=original;else await returnAfterCommitted(original);}else notice.value=canRetry.value?'暂未查到提交结果，请继续核对或按原操作键重试同一次请求。':'暂未查到结果；旧记录缺少原请求内容，请保留待核对并联系维护人员核实。';},true);if(recovered)await afterRecoveredPayment(recovered);}
async function retryPending(){let recovered:StoredOperation|null=null;await run(async()=>{const original=pending.value;await retryOperation();foundNotCommitted.value=false;if(receivableForOperation(original)||financeOperationTarget(original))recovered=original;else await returnAfterCommitted(original);},true);if(recovered)await afterRecoveredPayment(recovered);}
onMounted(()=>{if(session.value)run(async()=>{const user=await request<Session['user']>('/auth/me');if(!['salesperson','hospital'].includes(user.role))throw new Error('管理员请使用PC端');await bootstrap();});});
</script>

<template>
 <view class="app">
  <view class="masthead"><text class="brand">饮片报价</text><text class="account" v-if="session">{{session.user.name}}</text><button class="text-button" v-if="session" @click="logout" :disabled="running||operationInFlight">退出</button></view>
  <view v-if="!session" class="login">
   <text class="eyebrow">销售工作台 · 开发试用</text><text class="title">登录</text>
   <text class="subtle">本批试用：采购、询价、计价、文件导出、医院实际确认及回款登记。数据保存到试用服务器。</text>
   <view class="tabs"><button :class="{active:loginMode==='trial'}" @click="loginMode='trial'" :disabled="busy">开发试用</button><button :class="{active:loginMode==='wechat'}" @click="loginMode='wechat'" :disabled="busy">微信绑定</button></view>
   <view v-if="loginMode==='wechat'&&!bindTicket"><text class="subtle">需配置真实微信 AppID 与服务端密钥；未配置时会提示暂不可用。</text><button class="primary" @click="wechatLogin" :disabled="busy">微信登录 / 绑定销售账号</button></view>
   <view v-if="bindTicket" class="tabs"><button :disabled="busy" @click="bindingRole='sales'">绑定内部销售账号</button><button :disabled="busy" @click="bindingRole='hospital'">绑定医院采购员</button></view><view v-if="bindTicket&&bindingRole==='hospital'" class="form"><text class="subtle">手机号必须已由管理员建档并关联医院，系统不会自动注册。</text><button open-type="getPhoneNumber" :disabled="busy" @getphonenumber="hospitalPhoneLogin">授权手机号并绑定采购员</button></view><view v-if="loginMode==='trial'||bindTicket&&bindingRole==='sales'" class="form">
    <text v-if="bindTicket" class="notice">请绑定已有内部销售账号</text>
    <label class="field"><text>销售账号</text><input v-model="loginName" :disabled="busy" placeholder="请输入销售账号" autocomplete="username" /></label>
    <label class="field"><text>密码</text><input v-model="password" :disabled="busy" password placeholder="请输入密码" autocomplete="current-password" /></label>
    <button class="primary" @click="login" :disabled="busy||!loginName||!password">{{busy?'正在登录…':bindTicket?'绑定并登录':'登录开发试用'}}</button>
    <text class="subtle small">开发试用登录由服务器控制，仅用于非生产环境。</text>
   </view>
  </view>
  <template v-else>
   <view v-if="session.user.role==='salesperson'" class="navigation"><button class="text-button" @click="showOrders" :disabled="interactionLocked">采购单</button><button class="text-button" @click="showArchive" :disabled="interactionLocked">历史订单</button><button class="text-button" @click="showReceivables" :disabled="interactionLocked">回款台账</button><button class="text-button" @click="showFinance()" :disabled="interactionLocked">账期与催收</button><button class="text-button" @click="showHistorical" :disabled="interactionLocked">历史纸单补录</button><button class="text-button" @click="showAnalysis" :disabled="interactionLocked">医院分析</button><text v-if="order&&screen!=='archive'&&screen!=='receivables'&&screen!=='finance'">{{order.orderNo}} · R{{order.revisionNo}}</text><button v-if="session.user.role==='salesperson'&&screen==='delivery'&&!readOnly" class="text-button" @click="viewInquiry" :disabled="interactionLocked">厂家询价</button><button class="text-button" @click="refresh" :disabled="interactionLocked">重新加载</button></view>
   <view v-if="readOnly&&screen!=='orders'&&screen!=='archive'&&screen!=='receivables'&&screen!=='finance'" class="notice">{{order?.status==='completed'?'订单已完成，只能查阅报价和已有文件。':order?.status==='voided'?'订单已作废，保留历史查阅。':'当前订单只读；写操作仅限当前负责销售员。'}}</view>
   <HospitalWorkspace v-if="session.user.role==='hospital'&&screen!=='sourceRecovery'" ref="hospitalRef" :locked="running||!!pending" @busy-changed="hospitalBusy=$event" @failure="archiveFailure"/>
   <HistoricalOrders v-if="session.user.role==='salesperson'&&screen==='historical'" ref="historicalRef" :locked="running" @busy-changed="historicalBusy=$event" @failure="archiveFailure" @open-finance="showFinance"/>
   <HospitalAnalytics v-if="session.user.role==='salesperson'&&screen==='analytics'" ref="analyticsRef" :locked="running||!!pending" @busy-changed="analyticsBusy=$event" @failure="archiveFailure" @open-order="analysisOrder"/>
   <view v-if="screen==='sourceRecovery'&&sourceRecovery" class="workspace"><text class="title">原单操作核对</text><SourceFiles :key="session.user.id" :reference="sourceRecovery" :locked="running||!!pending" @busy-changed="sourceBusy=$event" @failure="archiveFailure"/></view>
   <view v-if="session.user.role==='salesperson'&&order&&['purchase','inquiry','pricing','delivery'].includes(screen)&&!readOnly" class="navigation"><button v-if="order.status!=='draft'" :disabled="interactionLocked" @click="beginOrderAction('revisions')">创建下一采购修订</button><button :disabled="interactionLocked" @click="beginOrderAction('void')">整单作废</button><button :disabled="interactionLocked||hasChanges" @click="showFinance({orderId:order.id})">单笔账期</button></view><view v-if="orderAction" class="section"><text class="section-title">{{orderAction==='revisions'?'创建下一采购修订':'整张采购单作废'}}</text><text class="subtle">{{orderAction==='revisions'?'旧采购明细、报价及文件保留；旧厂家入口关闭，旧医院报价不再接受确认。新修订重新校对和询价，不回退旧版。':'终止本次需求，关闭填写入口，从需求统计排除；历史和文件保留。最终确认或应收产生后禁止此操作。'}}</text><textarea v-model="orderActionReason" maxlength="500" :disabled="busy||!!pending" placeholder="请填写操作原因"/><button class="primary" :disabled="busy||!!pending||!orderActionReason.trim()" @click="commitOrderAction">确认执行</button><button :disabled="busy||!!pending" @click="orderAction=null">取消</button></view>
   <Receivables v-if="session.user.role==='salesperson'&&screen==='receivables'" ref="receivablesRef" :locked="running||!!pending" @busy-changed="receivablesBusy=$event" @dirty-changed="receivablesDirty=$event" @failure="archiveFailure" @manage-finance="showFinance" />
   <FinanceWorkspace v-if="session.user.role==='salesperson'&&screen==='finance'" ref="financeRef" :initial-target="financeTarget||undefined" :reminder-configuration="reminderConfiguration" :locked="running||!!pending" @busy-changed="financeBusy=$event" @failure="archiveFailure" />
   <OrderArchive v-if="session.user.role==='salesperson'&&screen==='archive'" ref="archiveRef" :locked="running||!!pending" @busy-changed="archiveBusy=$event" @failure="archiveFailure" @process-order="archiveProcess" />
   <view v-if="session.user.role==='salesperson'&&screen==='orders'" class="workspace">
    <view class="section-head"><text class="title">我的采购单</text><button class="primary compact" @click="startPurchase" :disabled="interactionLocked">新建采购单</button></view>
    <text v-if="busy" class="empty">正在读取采购单…</text><text v-else-if="!orders.length" class="empty">暂无采购单，开始录入第一张。</text>
    <button v-for="item in orders" :key="item.id" class="order-row" @click="openOrder(item.id)" :disabled="interactionLocked"><view><text class="row-title">{{item.hospitalName}}</text><text class="subtle small">{{item.orderNo}} · {{item.receivedDate}}</text></view><text class="tag">{{orderLabel(item.status)}} ›</text></button>
   </view>
   <view v-if="session.user.role==='salesperson'&&screen==='purchase'" class="workspace"><view class="section"><text class="section-title">采购原单与录入来源</text><SourceFiles v-if="order" :key="order.id+order.revisionId" :reference="{kind:'purchase_revision',orderId:order.id,revisionId:order.revisionId}" :order-version="order.version" :readonly="readOnly||order.status!=='draft'" :locked="running||deliveryBusy||archiveBusy||historyBusy||hasChanges||!!pending" @busy-changed="sourceBusy=$event" @failure="archiveFailure" @changed="sourceChanged"/><button v-else :disabled="interactionLocked" @click="sourceDraft">先建立原单资料草稿，再上传图片或表格</button><button :disabled="editingLocked||!isDraftOrder" @click="catalogOpen=!catalogOpen">从商品库选择规格</button><view v-if="catalogOpen"><input v-model="catalogKeyword" :disabled="interactionLocked" placeholder="输入品名、别名或规格"/><button :disabled="interactionLocked" @click="searchCatalog">查询商品库</button><view v-for="v in catalogItems" :key="v.variantId"><text>{{v.name}} · {{v.specification}} · {{v.origin}}</text><button :disabled="editingLocked" @click="chooseCatalog(v)">选择此规格</button></view></view></view>
    <button v-if="order" class="text-button" @click="viewDelivery" :disabled="interactionLocked">查看历史报价交付</button>
    <text class="eyebrow">手工采购</text><text class="title">采购录入与校对</text>
    <view class="form two">
     <label class="field"><text>医院</text><picker data-testid="hospital-picker" :disabled="interactionLocked||!!order" :range="hospitals" range-key="name" :value="hospitalIndex" @change="hospitalIndex=pickValue($event);purchaserIndex=0"><view class="select">{{order?order.hospitalName:hospital?.name||'请选择医院'}}⌄</view></picker></label>
     <label class="field"><text>采购员</text><picker data-testid="purchaser-picker" :disabled="interactionLocked||!!order" :range="hospital?.purchasers||[]" range-key="name" :value="purchaserIndex" @change="purchaserIndex=pickValue($event)"><view class="select">{{order?(hospitals.find(h=>h.id===order!.hospitalId)?.purchasers.find(p=>p.id===order!.purchaserUserId)?.name||'原单采购员（已关联）'):purchaser?.name||'请选择采购员'}}⌄</view></picker></label>
    </view>
    <label class="field date-field"><text>实际接收日期</text><picker data-testid="received-date" mode="date" :disabled="interactionLocked||!!order&&!order.receivedDateEditable" :value="receivedDate" @change="receivedDate=($event as any).detail.value;changed()"><view class="select">{{receivedDate}}</view></picker></label>
    <view class="section-head"><text class="section-title">采购明细 · {{lines.length}} 行</text><text class="subtle small">统一 kg</text></view>
    <view v-for="(line,index) in lines" :key="line.id||index" class="purchase-line">
     <view class="section-head"><text class="index">{{String(index+1).padStart(2,'0')}}</text><button class="text-button" :disabled="editingLocked||lines.length===1" @click="lines.splice(index,1);changed()">删除本行</button></view>
     <label class="field"><text>品名</text><input :data-testid="'purchase-name-'+index" :disabled="editingLocked" v-model="line.name" placeholder="填写医院原始品名" @input="line.checked=false;changed()" /></label>
     <view class="two"><label class="field"><text>规格（选填）</text><input :disabled="editingLocked" v-model="line.spec" placeholder="未提供可留空" @input="line.checked=false;changed()" /></label><label class="field"><text>数量 kg</text><input :disabled="editingLocked" v-model="line.quantity" type="digit" placeholder="0.00" @input="line.checked=false;changed()" /></label></view>
     <label class="field"><text>采购备注（选填）</text><input :disabled="editingLocked" v-model="line.remark" maxlength="500" @input="line.checked=false;changed()" /></label>
     <label class="check-row" :data-testid="'purchase-check-'+index" @click="!interactionLocked&&!readOnly&&(line.checked=!line.checked)"><checkbox :disabled="editingLocked" :checked="line.checked" color="#216349" /><text>已核对品名、规格和数量</text></label>
    </view>
    <button class="secondary full" :disabled="editingLocked" @click="lines.push(emptyLine());changed()">＋ 添加采购行</button>
    <view class="action-bar"><button class="secondary" @click="savePurchase" :disabled="interactionLocked||readOnly">保存草稿</button><button class="primary" @click="freeze" :disabled="interactionLocked||readOnly">校对完成并冻结</button></view>
   </view>
   <view v-if="session.user.role==='salesperson'&&screen==='inquiry'&&order" class="workspace">
    <button class="secondary full" @click="viewDelivery" :disabled="interactionLocked">查看报价交付与历史版本</button>
    <text class="eyebrow">{{order.hospitalName}} · {{order.lines.length}} 行</text><text class="title">厂家询价</text>
    <view v-for="slot in [1,2]" :key="slot" class="supplier-section">
     <view class="section-head"><text class="section-title">厂家 {{slot===1?'A':'B'}}</text><text class="tag">{{taskFor(slot)?.status==='submitted'?'已完整提交':taskFor(slot)?.status==='requote'?'重新报价中':taskFor(slot)?'待提交':'待选择'}}</text></view>
     <template v-if="!taskFor(slot)"><picker :data-testid="'manufacturer-picker-'+slot" :disabled="editingLocked" :range="manufacturers" range-key="name" :value="selectedFactory[slot-1]" @change="selectedFactory[slot-1]=pickValue($event)"><view class="select">{{manufacturers[selectedFactory[slot-1]||0]?.name||'请选择厂家'}} ⌄</view></picker><button class="secondary full" @click="assign(slot as 1|2)" :disabled="interactionLocked||readOnly">确认询价厂家</button></template>
     <template v-else><text class="row-title">{{taskFor(slot)!.manufacturerName}}</text><text class="subtle small">填写截止：{{stamp(taskFor(slot)!.linkExpiresAt)}}</text><text v-if="taskFor(slot)!.validUntil" class="subtle small">报价有效至 {{taskFor(slot)!.validUntil}}（含当日）</text>
      <view class="button-row" v-if="taskFor(slot)!.status!=='submitted'"><button v-if="!taskFor(slot)!.linkId" class="primary" @click="generate(taskFor(slot)!)" :disabled="interactionLocked||readOnly">生成填写链接</button><button v-else-if="generated[taskFor(slot)!.id]?.url" :disabled="editingLocked" class="primary" @click="copyLink(taskFor(slot)!)">复制厂家链接</button><button v-else class="secondary" :disabled="editingLocked" @click="danger={mode:'regenerate',task:taskFor(slot)!,reason:''}">重新生成链接</button><button class="text-button" :disabled="editingLocked" @click="danger={mode:'cancel',task:taskFor(slot)!,reason:''}">取消 / 换厂家</button></view>
      <view class="button-row" v-else><button class="secondary" :disabled="editingLocked" @click="danger={mode:'requote',task:taskFor(slot)!,reason:''}">重新询价并生成新链接</button><button class="text-button" :disabled="editingLocked" @click="danger={mode:'cancel',task:taskFor(slot)!,reason:''}">取消任务</button></view>
      <text v-if="taskFor(slot)!.linkId&&!generated[taskFor(slot)!.id]?.url&&taskFor(slot)!.status!=='submitted'" class="subtle small">原链接只在生成时返回，离开页面后须重新生成。</text>
     </template>
    </view>
    <view class="section-head"><text class="section-title">本次报价对照</text><button class="text-button" @click="run(loadComparison)" :disabled="interactionLocked">刷新报价</button></view>
    <view class="compare-table" v-if="comparison"><view class="table-row table-head"><text>药品 / 数量</text><text>A</text><text>B</text><text>最低</text></view><view v-for="row in comparison.lines" :key="row.purchaseLineId" class="table-row"><view><text class="drug">{{row.name}}</text><text class="subtle tiny">{{row.spec||'未提供规格'}}<br/>{{row.quantity}} kg</text></view><view v-for="slot in [1,2]" :key="slot"><template v-if="row.cells.find(c=>c.taskId===taskFor(slot)?.id)"><text>{{money(row.cells.find(c=>c.taskId===taskFor(slot)?.id)?.price)}}</text><text class="tiny subtle">{{stateLabels[row.cells.find(c=>c.taskId===taskFor(slot)?.id)!.state]}}</text></template><text v-else class="subtle tiny">未询价</text></view><text>{{row.kind==='missing'?'缺货':row.kind==='blocked'?'待齐':money(row.lowestPrice)}}</text></view></view>
    <view class="action-bar"><button v-if="order.draftId" class="primary full" @click="continuePricing" :disabled="interactionLocked">{{readOnly?'查看计价草稿':'继续计价草稿'}}</button><button v-else class="primary full" @click="enterPricing" :disabled="interactionLocked||readOnly||!order.quoteId&&!comparison?.submittedCount">{{order.quoteId&&!order.draftId?'查看报价版本':comparison?.submittedCount===1?'提前进入计价':'进入计价'}}</button></view>
   </view>
   <view v-if="session.user.role==='salesperson'&&screen==='pricing'&&draft" class="workspace">
    <view class="section-head"><view><text class="eyebrow">{{order?.hospitalName}}</text><text class="title">计价草稿</text></view><button class="text-button" @click="refreshCandidates" :disabled="interactionLocked">刷新报价候选</button><button class="text-button" @click="viewInquiry" :disabled="interactionLocked">查看询价</button></view>
    <view v-if="changedSupplier" class="notice"><text>有新的厂家报价，当前草稿保留原快照。</text><button class="text-button" @click="adopt" :disabled="interactionLocked||readOnly">采用最新报价{{selectedLineIds.length?'（选中行）':'（全部行）'}}</button></view>
    <view class="batch"><text class="section-title">批量加价</text><view class="two"><picker data-testid="markup-method" :disabled="editingLocked" :range="methodLabels" :value="methodIndex" @change="methodIndex=pickValue($event)"><view class="select">{{methodLabels[methodIndex]}} ⌄</view></picker><input class="input" :disabled="editingLocked" v-model="parameter" type="digit" :placeholder="methodIndex===3?'例如 1.2':'填写加价参数'" /></view><view class="two"><picker data-testid="markup-scope" :disabled="interactionLocked" :range="['全部可计价行','选中行']" :value="batchScope" @change="batchScope=pickValue($event)"><view class="select">{{batchScope===0?'全部可计价行':'选中行'}} ⌄</view></picker><text class="subtle">将影响 {{batchLines.length}} 行</text></view><view class="button-row"><button class="secondary" :disabled="editingLocked" @click="applyBatch">更新推荐价</button><button class="text-button" @click="undoBatch" :disabled="interactionLocked||!undo||readOnly">撤销最近批量</button></view></view>
    <view class="compare-table"><view class="table-row table-head"><text>选择 / 药品</text><text>基准</text><text>推荐</text><text>最终</text></view><view v-for="line in draft.lines" :key="line.purchaseLineId" class="table-row editable" :class="{current:activeLineId===line.purchaseLineId}" @click="!interactionLocked&&(activeLineId=line.purchaseLineId)"><view><view class="select-drug"><checkbox :disabled="interactionLocked" :checked="selectedLineIds.includes(line.purchaseLineId)" color="#216349" @click.stop="toggleLine(line.purchaseLineId)"/><text class="drug">{{line.name}}</text></view><text class="tiny subtle">{{line.spec||'未提供规格'}} · {{line.quantity}} kg</text></view><view><text>{{line.kind==='missing'?'缺货':line.kind==='blocked'?'待齐':money(line.basePrice)}}</text><text class="tiny subtle">{{line.baseManufacturerName||''}}</text><text v-if="!line.baseValid&&line.kind==='priced'||line.kind==='missing'&&line.supplyValid===false" class="tiny warning">依据已失效</text></view><text>{{money(line.recommendedPrice)}}</text><view><text>{{line.kind==='missing'?'缺货':money(line.finalPrice)}}</text><text class="tiny subtle">{{line.finalConfirmed?'已确认':'待确认'}}</text></view></view></view>
    <view v-if="activeLine" class="line-editor"><text class="section-title">{{activeLine.name}} · 逐行计价</text><text class="subtle small">{{activeLine.spec||'未提供规格'}} · {{activeLine.quantity}} kg</text>
     <PriceHistory v-if="order" :key="activeLine.purchaseLineId" :hospital-id="order.hospitalId" :order-id="order.id" :name="activeLine.name" :spec="activeLine.spec" :final-price="activeLine.finalPrice" :locked="running||deliveryBusy||archiveBusy||!!pending" @busy-changed="historyBusy=$event" @failure="archiveFailure" />
     <view v-if="activeLine.kind==='priced'">
      <label class="field"><text>基准厂家（只选当前有效报价）</text><picker data-testid="base-manufacturer" :disabled="editingLocked" :range="activeComparison?.cells.filter(c=>c.state==='quoted').map(c=>c.manufacturerName+' · '+c.price+' 元/kg')||[]" @change="chooseBase"><view class="select">{{activeLine.baseManufacturerName||'请选择有效基准'}} · {{money(activeLine.basePrice)}} ⌄</view></picker></label><text class="tiny subtle">{{activeLine.selectionMode==='manual'?'手动锁定基准厂家':'自动采用最低有效价'}} · 当前基准{{activeLine.baseValid?'有效':'已失效'}}</text>
      <view class="recommend"><text>推荐价 {{money(activeLine.recommendedPrice)}} 元/kg</text><button class="text-button" @click="applyRecommended(activeLine)" :disabled="interactionLocked||!activeLine.recommendedPrice||readOnly">采用为最终价</button></view>
      <label class="field"><text>最终报价 元/kg</text><input :disabled="editingLocked" v-model="activeLine.finalPrice" type="digit" placeholder="填写或采用推荐价" @input="finalChanged(activeLine)" /></label>
      <label class="field" v-if="activeLine.finalPrice&&activeLine.basePrice&&Number(activeLine.finalPrice)<Number(activeLine.basePrice)"><text class="warning">低于基准价，请填写亏损原因</text><textarea :disabled="editingLocked" v-model="activeLine.lossReason" placeholder="填写本次低价原因" @input="activeLine.finalConfirmed=false;changed()" /></label>
      <label class="check-row"><switch data-testid="final-confirmed" :checked="activeLine.finalConfirmed" color="#216349" @change="activeLine.finalConfirmed=($event as any).detail.value;changed()" :disabled="interactionLocked||!activeLine.finalPrice||!activeLine.baseValid||readOnly"/><text>已核对最终价{{activeLine.finalPrice&&activeLine.basePrice&&Number(activeLine.finalPrice)<Number(activeLine.basePrice)?'并确认亏损风险':''}}</text></label>
     </view>
     <label class="field"><text>医院公开备注（选填）</text><textarea :disabled="editingLocked" v-model="activeLine.publicRemark" maxlength="500" placeholder="会显示在医院报价单中，请勿填写成本或内部原因" @input="changed()" /></label>
     <text v-if="activeLine.kind!=='priced'" class="subtle">{{activeLine.kind==='missing'?'两家均明确无法供货；保留原行，不参与金额计算。':'厂家报价尚未齐备，当前行暂不能计价。'}}</text>
    </view>
    <label class="field"><text>医院报价有效至（最长 {{draft.maxValidUntil||(allMissing?'不适用':'尚无有效基准')}}）</text><picker mode="date" :value="draft.hospitalValidUntil||''" :end="draft.maxValidUntil||undefined" @change="draft.hospitalValidUntil=($event as any).detail.value;changed()" :disabled="interactionLocked||!draft.maxValidUntil||readOnly"><view class="select">{{draft.hospitalValidUntil||(allMissing?'不适用（全部缺货）':'尚无有效基准')}}</view></picker></label>
    <view class="total"><text>服务器已保存总额</text><text>{{draft.total==null?(allMissing?'不适用（全部缺货）':'待完成计价'):'¥ '+draft.total}}</text></view>
    <view class="action-bar"><button class="secondary" @click="viewDelivery" :disabled="interactionLocked||hasChanges">报价交付</button><button class="primary full" @click="saveDraft" :disabled="interactionLocked||readOnly">保存计价草稿</button></view>
   </view>
   <QuoteDelivery ref="deliveryRef" v-if="session.user.role==='salesperson'&&screen==='delivery'&&order" :key="order.id" :order-id="order.id" :writable="!readOnly" :locked="busy||!!pending" @busy-changed="deliveryBusy=$event" @failure="deliveryFailure" @changed="deliveryChanged" @edit-draft="editDeliveryDraft" />
  </template>
  <view v-if="notice" class="notice status">{{notice}}</view><view v-if="error" class="error" role="alert">{{error}}<button class="text-button" v-if="conflict" @click="refresh">重新加载最新数据（放弃本地修改）</button></view>
  <view v-if="pending" class="pending"><text>「{{pending.label}}」结果待核实</text><button class="secondary" @click="checkPending" :disabled="running||operationInFlight">核对操作结果</button><button v-if="foundNotCommitted&&canRetry" class="text-button" :disabled="running||operationInFlight" @click="retryPending">重新提交同一次请求</button><text v-if="foundNotCommitted&&!canRetry" class="subtle small">旧记录缺少原请求内容，请保留待核对并联系维护人员核实。</text></view>
  <view class="overlay" v-if="danger"><view class="dialog"><text class="section-title">{{danger.mode==='requote'?'重新询价并生成新链接':danger.mode==='cancel'?'取消本次厂家任务':'重新生成填写链接'}}</text><text class="subtle">{{danger.mode==='requote'?'旧提交立即退出计算，相关基准及未完成医院报价失效，最终价保留但须重新核对。':danger.mode==='cancel'?'旧链接和本次有效提交立即退出计算；历史记录保留。':'旧链接及已打开的旧填写页面立即失效，新链接从现在起有效 48 小时。'}}</text><label class="field"><text>操作原因</text><textarea :disabled="busy" v-model="danger.reason" placeholder="请填写原因" /></label><view class="button-row"><button class="secondary" @click="danger=null" :disabled="busy">返回</button><button class="primary" @click="commitDanger" :disabled="busy||!danger.reason.trim()">确认操作</button></view></view></view>
 </view>
</template>

